1	package com.loja.checkout;
2	
3	import com.loja.checkout.clube.NivelClube;
4	import com.loja.checkout.clube.NiveisClube;
5	import com.loja.checkout.cupom.ContextoCupom;
6	import com.loja.checkout.cupom.Cupom;
7	import com.loja.checkout.cupom.Cupons;
8	import com.loja.checkout.dominio.CheckoutException;
9	import com.loja.checkout.dominio.Dinheiro;
10	import com.loja.checkout.dominio.ErroCheckout;
11	import com.loja.checkout.dominio.ItemPedido;
12	import com.loja.checkout.dominio.Regiao;
13	import com.loja.checkout.entrega.ModalidadeEntrega;
14	import com.loja.checkout.entrega.ModalidadesEntrega;
15	import com.loja.checkout.pagamento.Cobranca;
16	import com.loja.checkout.pagamento.FormaPagamento;
17	import com.loja.checkout.pagamento.FormasPagamento;
18	import com.loja.checkout.web.ResumoRequest;
19	import com.loja.checkout.web.ResumoResponse;
20	import java.math.BigDecimal;
21	import java.util.ArrayList;
22	import java.util.List;
23	import org.springframework.stereotype.Service;
24	
25	/**
26	 * Calcula o resumo da compra: confere o pedido na ordem definida e monta o
27	 * resultado pedindo a cada eixo (entrega, cupom, clube, regiao, pagamento) a
28	 * sua parte da conta.
29	 */
30	@Service
31	public class ResumoCheckoutService {
32	
33	    private static final int PARCELA_UNICA = 1;
34	
35	    public ResumoResponse calcular(ResumoRequest pedido) {
36	        List<ItemPedido> itens = itensDe(pedido);
37	        NivelClube nivel = NiveisClube.REGISTRO.buscar(pedido.nivelClube())
38	                .orElseThrow(() -> recusa(ErroCheckout.NIVEL_CLUBE_INVALIDO));
39	        Regiao regiao = Regiao.porCodigo(pedido.regiao())
40	                .orElseThrow(() -> recusa(ErroCheckout.REGIAO_INVALIDA));
41	        ModalidadeEntrega modalidade = ModalidadesEntrega.REGISTRO.buscar(pedido.modalidadeEntrega())
42	                .orElseThrow(() -> recusa(ErroCheckout.MODALIDADE_INVALIDA));
43	
44	        BigDecimal pesoKg = pesoDe(itens);
45	        if (!modalidade.atende(pesoKg)) {
46	            throw recusa(ErroCheckout.MODALIDADE_INDISPONIVEL);
47	        }
48	
49	        BigDecimal subtotalProdutos = subtotalDe(itens);
50	        BigDecimal frete = nivel.frete(modalidade.frete(pesoKg));
51	        BigDecimal descontoCupom = descontoDe(pedido.cupom(), new ContextoCupom(itens, subtotalProdutos, frete));
52	        BigDecimal seguro = regiao.seguro(subtotalProdutos);
53	        BigDecimal totalPedido = Dinheiro.arredonda(
54	                subtotalProdutos.subtract(descontoCupom).add(frete).add(seguro));
55	
56	        FormaPagamento formaPagamento = FormasPagamento.REGISTRO.buscar(pedido.formaPagamento())
57	                .orElseThrow(() -> recusa(ErroCheckout.FORMA_PAGAMENTO_INVALIDA));
58	        int parcelas = pedido.parcelas() == null ? PARCELA_UNICA : pedido.parcelas();
59	        if (!formaPagamento.aceitaParcelas(parcelas)) {
60	            throw recusa(ErroCheckout.PARCELAMENTO_INVALIDO);
61	        }
62	        if (!formaPagamento.atende(totalPedido)) {
63	            throw recusa(ErroCheckout.FORMA_PAGAMENTO_INDISPONIVEL);
64	        }
65	        Cobranca cobranca = formaPagamento.cobrar(totalPedido, parcelas);
66	
67	        return new ResumoResponse(
68	                subtotalProdutos,
69	                descontoCupom,
70	                frete,
71	                modalidade.prazoDias(),
72	                seguro,
73	                Dinheiro.arredonda(cobranca.totalFinal().subtract(totalPedido)),
74	                cobranca.totalFinal(),
75	                parcelas,
76	                cobranca.valorParcela(),
77	                nivel.credito(subtotalProdutos),
78	                nivel.brinde(subtotalProdutos));
79	    }
80	
81	    /** O carrinho precisa ter itens, e todo item precisa de preco, quantidade e peso. */
82	    private List<ItemPedido> itensDe(ResumoRequest pedido) {
83	        if (pedido.itens() == null || pedido.itens().isEmpty()) {
84	            throw recusa(ErroCheckout.PEDIDO_INVALIDO);
85	        }
86	        List<ItemPedido> itens = new ArrayList<>();
87	        for (ResumoRequest.ItemRequest item : pedido.itens()) {
88	            if (item == null || !positivo(item.precoUnitario()) || !positivo(item.quantidade())
89	                    || !positivo(item.pesoKg())) {
90	                throw recusa(ErroCheckout.PEDIDO_INVALIDO);
91	            }
92	            itens.add(new ItemPedido(item.nome(), item.precoUnitario(), item.quantidade(), item.pesoKg()));
93	        }
94	        return itens;
95	    }
96	
97	    private boolean positivo(BigDecimal valor) {
98	        return valor != null && valor.compareTo(BigDecimal.ZERO) > 0;
99	    }
100	
101	    private boolean positivo(Integer valor) {
102	        return valor != null && valor > 0;
103	    }
104	
105	    private BigDecimal subtotalDe(List<ItemPedido> itens) {
106	        BigDecimal subtotal = BigDecimal.ZERO;
107	        for (ItemPedido item : itens) {
108	            subtotal = subtotal.add(item.total());
109	        }
110	        return Dinheiro.arredonda(subtotal);
111	    }
112	
113	    /** O peso do pedido nao e arredondado. */
114	    private BigDecimal pesoDe(List<ItemPedido> itens) {
115	        BigDecimal peso = BigDecimal.ZERO;
116	        for (ItemPedido item : itens) {
117	            peso = peso.add(item.peso());
118	        }
119	        return peso;
120	    }
121	
122	    private BigDecimal descontoDe(String codigo, ContextoCupom contexto) {
123	        if (codigo == null) {
124	            return Dinheiro.ZERO;
125	        }
126	        Cupom cupom = Cupons.REGISTRO.buscar(codigo)
127	                .orElseThrow(() -> recusa(ErroCheckout.CUPOM_INVALIDO));
128	        if (!cupom.aplicavel(contexto)) {
129	            throw recusa(ErroCheckout.CUPOM_NAO_APLICAVEL);
130	        }
131	        return cupom.desconto(contexto);
132	    }
133	
134	    private CheckoutException recusa(ErroCheckout erro) {
135	        return new CheckoutException(erro);
136	    }
137	}
