7	/** Arredondamento do dinheiro: centavos, meio para o par, em cada etapa. */
8	public final class Dinheiro {
9	
10	    public static final BigDecimal ZERO = arredonda(BigDecimal.ZERO);
11	
12	    /** Precisao de trabalho das contas intermediarias (divisoes e potencias). */
13	    public static final MathContext CONTAS = MathContext.DECIMAL128;
14	
15	    private static final int CENTAVOS = 2;
16	
17	    private Dinheiro() {
18	    }
19	
20	    public static BigDecimal arredonda(BigDecimal valor) {
21	        return valor.setScale(CENTAVOS, RoundingMode.HALF_EVEN);
22	    }
23	
24	    /** Porcentagem sobre uma base, ja arredondada para centavos. */
25	    public static BigDecimal percentual(BigDecimal base, BigDecimal taxa) {
26	        return arredonda(base.multiply(taxa));
27	    }
28	}
