8	/**
9	 * Registro de casos de um eixo (entrega, cupom, clube, pagamento): a escolha do
10	 * caso e sempre uma busca pelo codigo, nunca uma sequencia de condicoes.
11	 */
12	public final class Registro<T extends Registro.Identificado> {
13	
14	    /** Todo caso registrado se identifica pelo codigo que o site envia. */
15	    public interface Identificado {
16	        String codigo();
17	    }
18	
19	    private final Map<String, T> porCodigo;
20	
21	    @SafeVarargs
22	    public Registro(T... casos) {
23	        Map<String, T> mapa = new LinkedHashMap<>();
24	        for (T caso : casos) {
25	            mapa.put(caso.codigo(), caso);
26	        }
27	        this.porCodigo = Map.copyOf(mapa);
28	    }
29	
30	    public Optional<T> buscar(String codigo) {
31	        return codigo == null ? Optional.empty() : Optional.ofNullable(porCodigo.get(codigo));
32	    }
33	
34	    public List<String> codigos() {
35	        return List.copyOf(porCodigo.keySet());
36	    }
37	}
