1	package com.loja.checkout.pagamento;
2	
3	import com.loja.checkout.dominio.Dinheiro;
4	import java.math.BigDecimal;
5	
6	/** Ate 3x sem juros; de 4x a 12x com juros de 1,99% ao mes (tabela Price). */
7	public final class Cartao implements FormaPagamento {
8	
9	    private static final int PARCELAS_MAXIMAS = 12;
10	    private static final int PARCELAS_SEM_JUROS = 3;
11	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
12	
13	    @Override
14	    public String codigo() {
15	        return "CARTAO";
16	    }
17	
18	    @Override
19	    public boolean aceitaParcelas(int parcelas) {
20	        return parcelas >= 1 && parcelas <= PARCELAS_MAXIMAS;
21	    }
22	
23	    @Override
24	    public Cobranca cobrar(BigDecimal totalPedido, int parcelas) {
25	        if (parcelas <= PARCELAS_SEM_JUROS) {
26	            return semJuros(totalPedido, parcelas);
27	        }
28	        return comJuros(totalPedido, parcelas);
29	    }
30	
31	    /** O valor final e o proprio total do pedido; a parcela e o total dividido. */
32	    private Cobranca semJuros(BigDecimal totalPedido, int parcelas) {
33	        BigDecimal valorParcela = Dinheiro.arredonda(
34	                totalPedido.divide(BigDecimal.valueOf(parcelas), Dinheiro.CONTAS));
35	        return new Cobranca(Dinheiro.arredonda(totalPedido), valorParcela);
36	    }
37	
38	    /** parcela = total x taxa / (1 - (1 + taxa)^-parcelas); final = parcela x parcelas. */
39	    private Cobranca comJuros(BigDecimal totalPedido, int parcelas) {
40	        BigDecimal fator = BigDecimal.ONE.add(TAXA_MENSAL).pow(parcelas, Dinheiro.CONTAS);
41	        BigDecimal divisor = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(fator, Dinheiro.CONTAS));
42	        BigDecimal valorParcela = Dinheiro.arredonda(
43	                totalPedido.multiply(TAXA_MENSAL).divide(divisor, Dinheiro.CONTAS));
44	        BigDecimal totalFinal = Dinheiro.arredonda(valorParcela.multiply(BigDecimal.valueOf(parcelas)));
45	        return new Cobranca(totalFinal, valorParcela);
46	    }
47	}
