9	 */
10	public enum Regiao {
11	
12	    SUDESTE("0.010"),
13	    SUL("0.010"),
14	    CENTRO_OESTE("0.015"),
15	    NORTE("0.025"),
16	    NORDESTE("0.020");
17	
18	    private final BigDecimal aliquotaSeguro;
19	
20	    Regiao(String aliquotaSeguro) {
21	        this.aliquotaSeguro = new BigDecimal(aliquotaSeguro);
22	    }
23	
24	    /** Seguro contra extravio e roubo: a aliquota sobre o valor dos produtos. */
25	    public BigDecimal seguro(BigDecimal subtotalProdutos) {
26	        return Dinheiro.percentual(subtotalProdutos, aliquotaSeguro);
27	    }
