29	    public static Optional<Regiao> porCodigo(String codigo) {
30	        if (codigo == null) {
31	            return Optional.empty();
32	        }
33	        for (Regiao regiao : values()) {
34	            if (regiao.name().equals(codigo)) {
35	                return Optional.of(regiao);
36	            }
37	        }
38	        return Optional.empty();
39	    }
