    \@Test
    void limites_das_regras_valem_no_ponto() {
        ResumoResponse menos50NoMinimo = servico.calcular(pedido(List.of(item("Vestido", "300.00", 1, "0.40")),
                "RETIRADA_LOJA", "MENOS50", "PIX", 1, "BRONZE", "SUDESTE"));
